/// Look up an interface by its wire name (the `str` argument of
/// `wl_registry.bind`).
pub fn lookup(name: &str) -> Option<&'static Interface> {
    TABLE.iter().find(|(n, _)| *n == name).map(|(_, i)| *i)
}
